static uint8_t data_ready = 0;

void TIM2_IRQHandler(void) {
    if (TIM2->SR & TIM_SR_UIF) {
        TIM2->SR &= ~TIM_SR_UIF;
        data_ready = 1;
    }
}

int main(void) {
    init_timer();
    while (1) {
        while (!data_ready) { }
        data_ready = 0;
        sample_and_send();
    }
}
